package com.smartdoc.ai.provider;
import java.util.*; public class ProviderAdapterRegistry { private final Map<AiProviderProtocol,ProviderAdapter> adapters=new EnumMap<>(AiProviderProtocol.class); public ProviderAdapterRegistry(Collection<ProviderAdapter> list){for(ProviderAdapter a:list)adapters.put(a.protocol(),a);} public ProviderAdapter require(String value){try{return require(AiProviderProtocol.valueOf(value));}catch(IllegalArgumentException e){throw new ProviderHttpException("UNSUPPORTED_PROTOCOL",400);}} public ProviderAdapter require(AiProviderProtocol p){ProviderAdapter a=adapters.get(p);if(a==null)throw new ProviderHttpException("UNSUPPORTED_PROTOCOL",400);return a;} }
